import{_ as a,C as s,o as n,c as o,E as i,a3 as r}from"./chunks/framework.CCylkYel.js";const d="/screens/devices/delay.png",h="/screens/devices/delay-long.png",f=JSON.parse('{"title":"Delay","description":"","frontmatter":{"title":"Delay","pageClass":"device-doc"},"headers":[],"relativePath":"devices/delay.md","filePath":"devices/delay.md"}'),l={name:"devices/delay.md"};function g(c,t,y,p,u,b){const e=s("DeviceHeading");return n(),o("div",null,[i(e,{slug:"delay",title:"Delay"}),t[0]||(t[0]=r('<p>Delay notes in time</p><p><img src="'+d+'" alt="Delay: SYNCED, Delay Time 1/8, 4 repeats, Feedback 60%" class="screen"></p><p>The right side shows the dry note and each echo as bars. The first bar is the dry note, with a small pointer under it; its height follows <strong>Dry/Wet</strong>. The echoes follow at the <strong>Delay Time</strong> spacing and get shorter with <strong>Feedback</strong>. The echo that just played is White. With <strong>Infinite</strong> on, a fading tail follows the last bar.</p><p><img src="'+h+'" alt="Delay: SYNCED, Delay Time 1/2, 10 repeats, Feedback 80%" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Repeat notes in time with echoes, or thicken a phrase with a few quiet repeats.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>SYNCED</strong> follows the tempo and shows note values such as <strong>1/8</strong>. <strong>FREE</strong> uses milliseconds.</li><li>With <strong>Fixed Length</strong> on, each echo lasts <strong>Note Length</strong>. With it off, each echo lasts one <strong>Delay Time</strong>.</li><li>The rows always keep this order: <strong>Bypass</strong>, <strong>Sync</strong>, <strong>Delay Time</strong>, <strong>Infinite</strong>, <strong>Repetitions</strong>, <strong>Feedback</strong>, <strong>Dry/Wet</strong>, <strong>Fixed Length</strong>, <strong>Note Length</strong>, <strong>Overdub</strong>.</li><li>A row that does not apply stays where it is, dimmed: <strong>Note Length</strong> while <strong>Fixed Length</strong> is off, <strong>Repetitions</strong> while <strong>Infinite</strong> is on. Its value stays visible, the encoder skips it, and switching a row never moves the list.</li><li>Letting go of a key adds no extra echo. The echoes that are already playing finish on their own.</li><li><strong>Infinite</strong> is a hold switch. While it is on, echoes keep going past <strong>Repetitions</strong>; below <strong>Feedback</strong> 100% they still fade out. Turn it off and the tail you hear finishes its <strong>Repetitions</strong> and stops; a note that is already past that count plays one last echo. Turning <strong>Bypass</strong> on cuts every echo at once.</li><li><strong>Overdub</strong> on stacks a new echo line when you replay a note that is still echoing. Off, replaying that note plays only the dry note.</li></ul><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>0 – 1</td><td>When on, the device is disabled and MIDI passes through unchanged.</td></tr><tr><td>SYNC</td><td>0 – 1</td><td>SYNCED follows the tempo and shows note values such as 1/8. FREE uses milliseconds.</td></tr><tr><td>DELAY TIME</td><td>0 – 1000</td><td>The gap before each echo. SYNCED shows note values such as 1/8; FREE uses milliseconds.</td></tr><tr><td>INFINITE</td><td>0 – 1</td><td>A hold switch: while on, echoes keep going past Repetitions. Turn it off and the tail finishes its Repetitions (a line already past them plays one last echo) and stops. Bypass cuts the tail at once.</td></tr><tr><td>REPETITIONS</td><td>0 – 10</td><td>How many echoes play. Dimmed while Infinite is on.</td></tr><tr><td>FEEDBACK</td><td>0 – 100</td><td>How much each echo fades. 100% keeps them at full level.</td></tr><tr><td>DRY/WET</td><td>0 – 100</td><td>Balance between the original note and the echoes.</td></tr><tr><td>FIXED LENGTH</td><td>0 – 1</td><td>When on, each echo lasts Note Length. When off, each echo lasts one Delay Time.</td></tr><tr><td>NOTE LENGTH</td><td>0 – 1000</td><td>How long each echo lasts when Fixed Length is on. Stays on screen, dimmed, while Fixed Length is off.</td></tr><tr><td>OVERDUB</td><td>0 – 1</td><td>When on, replaying a note that is still echoing stacks a new echo line. When off, replaying it plays only the dry note.</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="bypass" tabindex="-1">Bypass <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;Bypass&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OFF</td><td>Device is active and processes MIDI.</td></tr><tr><td style="text-align:right;">1</td><td>ON</td><td>Device is bypassed; messages pass through unchanged.</td></tr></tbody></table><h3 id="infinite" tabindex="-1">Infinite <a class="header-anchor" href="#infinite" aria-label="Permalink to &quot;Infinite&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OFF</td><td>Every echo line ends after Repetitions. A line already past it plays one last echo.</td></tr><tr><td style="text-align:right;">1</td><td>ON</td><td>Echoes keep going past Repetitions. Below 100% Feedback they still fade out.</td></tr></tbody></table><h3 id="sync" tabindex="-1">Sync <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;Sync&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>FREE</td><td>Delay Time is in milliseconds.</td></tr><tr><td style="text-align:right;">1</td><td>SYNCED</td><td>Delay Time is a note value and follows the tempo (default).</td></tr></tbody></table><p>Switching to <strong>SYNCED</strong> sets <strong>Delay Time</strong> to the nearest note value.</p><h3 id="fixed-length" tabindex="-1">Fixed Length <a class="header-anchor" href="#fixed-length" aria-label="Permalink to &quot;Fixed Length&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OFF</td><td>Each echo lasts one Delay Time.</td></tr><tr><td style="text-align:right;">1</td><td>ON</td><td>Each echo lasts Note Length.</td></tr></tbody></table><h3 id="overdub" tabindex="-1">Overdub <a class="header-anchor" href="#overdub" aria-label="Permalink to &quot;Overdub&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OFF</td><td>Replaying a note that is still echoing plays only the dry note.</td></tr><tr><td style="text-align:right;">1</td><td>ON</td><td>Replaying a note that is still echoing stacks a new echo line.</td></tr></tbody></table>',22))])}const w=a(l,[["render",g]]);export{f as __pageData,w as default};
